const variant=new URLSearchParams(location.search).get('v')==='b'?'b':'a';
const app=document.querySelector('#app');
if(window.parent===window)document.documentElement.classList.add('solo');
const paths={play:'M9 5l11 7-11 7z',pause:'M8 5v14M16 5v14',home:'M3 10l9-7 9 7M5 9v12h5v-7h4v7h5V9',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8',bookmark:'M6 3h12v18l-6-4-6 4z',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M3 12h18M12 3c-6 5-6 13 0 18 6-5 6-13 0-18',feed:'M5 4h14v16H5zM8 1h8M8 23h8M10 8l6 4-6 4z',library:'M4 4v16M9 4v16M14 4l6 16',arrow:'M5 12h14M14 7l5 5-5 5',back:'M15 5l-7 7 7 7',down:'M6 9l6 6 6-6',next:'M7 5l9 7-9 7M20 5v14',prev:'M17 5l-9 7 9 7M4 5v14',close:'M6 6l12 12M6 18L18 6',more:'M4 12h.01M12 12h.01M20 12h.01',timer:'M9 2h6M12 7v6l3 2M20 13a8 8 0 1 1-16 0 8 8 0 0 1 16 0',palette:'M12 3a9 9 0 1 0 0 18c3 0 1-3 3-4s6 1 6-5a9 9 0 0 0-9-9M7 8h.01M12 6h.01M17 9h.01M6 13h.01',check:'M4 12l5 5L20 6',spark:'M12 2l3 7 7 3-7 3-3 7-3-7-7-3 7-3z',volume:'M4 9h4l5-4v14l-5-4H4zM17 8a6 6 0 0 1 0 8M20 5a10 10 0 0 1 0 14',queue:'M3 5h18M3 11h12M3 17h9M18 14l4 3-4 3z',link:'M10 13a5 5 0 0 0 7 0l4-4a5 5 0 0 0-7-7l-3 3M14 11a5 5 0 0 0-7 0l-4 4a5 5 0 0 0 7 7l3-3'};
const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.spark}"/></svg>`;
const esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const lira=()=>`<span class="lira-face" aria-hidden="true"><svg viewBox="0 0 64 64"><defs><linearGradient id="hair${Math.random().toString(36).slice(2)}"><stop stop-color="#ffa665"/><stop offset="1" stop-color="#ae435f"/></linearGradient></defs><circle cx="32" cy="32" r="30" fill="#eeb797"/><path d="M11 39C5 7 40-1 51 17c9 16 0 27 7 35H9z" fill="#693a48"/><path d="M20 25c0-14 27-15 26 4l-3 17c-4 11-18 11-21-1z" fill="#ffd8b2"/><path d="M17 26c13 0 17-8 18-13 8 3 9 11 13 15V16L27 7 16 18z" fill="#693a48"/><path d="M24 34l5 1m7 0 5-1" stroke="#693a48" stroke-width="2" stroke-linecap="round"/><path d="M29 43q5 4 9-1" fill="none" stroke="#b86362" stroke-width="2" stroke-linecap="round"/><path d="M13 35V25a20 20 0 0 1 40 0v10" fill="none" stroke="#f7d89d" stroke-width="4"/><rect x="9" y="30" width="9" height="15" rx="4" fill="#fff0c9"/><rect x="48" y="30" width="9" height="15" rx="4" fill="#fff0c9"/></svg></span>`;
const countries=[['France','Франция','Париж','FR'],['Japan','Япония','Токио','JP'],['Brazil','Бразилия','Рио','BR'],['The United Kingdom Of Great Britain And Northern Ireland','Британия','Лондон','GB'],['The United States Of America','США','Нью-Йорк','US'],['Switzerland','Швейцария','Берн','CH']];
const countryName=c=>countries.find(x=>x[0]===c)?.[1]||c;
const stories=[{id:'jazz',title:'Джаз без галстука',desc:'От камерного трио до свободного грува. Эфиры, в которых есть воздух.',tag:'jazz',art:'jazz',subtitle:'Импровизация / живой звук'}, {id:'night',title:'После последнего метро',desc:'Медленные ритмы, эмбиент и музыка для долгой дороги домой.',mood:'mood-late-night',art:'night',subtitle:'Downtempo / ambient / lounge'}, {id:'groove',title:'Тело знает ритм',desc:'Фанк, соул и басовые линии, которые сложно слушать неподвижно.',tag:'funk',art:'groove',subtitle:'Funk / soul / groove'}, {id:'world',title:'За пределами привычного',desc:'Радио с музыкой мира: иной язык, другой ритм, новая точка на карте.',tag:'world music',art:'world',subtitle:'Музыка без границ'}];
const state={stations:[],current:null,playing:false,tab:'home',country:0,theme:'light',atlasCache:{},favorites:new Set(),finds:[],queue:[],timer:0,volume:75,scrolls:{},overlayStack:[],generation:0};
const known=new Map();
let main,modal,toastTimer,timerHandle,focusBefore,feedStart;
const idOf=s=>s.stationuuid;
const shortName=s=>s.name.replace(' (128k MP3)','').replace(' Main Mix (EU) 320k AAC','');
const register=items=>items.forEach(s=>known.set(idOf(s),s));
function logo(s){const n=shortName(s);const brand=n==='FIP'?'fip':n.startsWith('TSF')?'tsf':n.includes('SomaFM')?'soma':n.includes('Paradise')?'rp':n.includes('Meuh')?'meuh':n.includes('NTS')?'nts':'generic';return `<span class="station-logo ${brand}" aria-hidden="true">${esc(brand==='generic'?n.slice(0,2):{fip:'fip',tsf:'TSF',soma:'soma',rp:'rp',meuh:'meuh',nts:'NTS'}[brand])}</span>`;}
const button=(action,label,ic,cls='',attrs='')=>`<button class="${cls}" data-action="${action}" aria-label="${esc(label)}" ${attrs}>${ic?icon(ic):''}<span>${esc(label)}</span></button>`;
const art=(kind)=>`<div class="poster-art ${kind}" aria-hidden="true"><div class="record"><i></i></div><div class="art-lines"></div><b>${({jazz:'jazz.',night:'slow\ndown',groove:'GOOD\nGROOVE',world:'ailleurs',feed:'ON AIR'})[kind]||'radio.'}</b><span>RADIOATLAS — EXPLORATIONS</span></div>`;
function row(s,{number='',queue=false}={}){return `<div class="station-row">${number?`<span class="row-number">${number}</span>`:''}<button class="source-open" data-action="source" data-id="${esc(idOf(s))}">${logo(s)}<span><strong>${esc(shortName(s))}</strong><small>${esc(countryName(s.country))}${s.tags?' · '+esc(s.tags.split(',').filter(t=>!['aac','mp3'].includes(t)).slice(0,2).join(' / ')):''}</small></span></button>${button(queue?'removequeue':'play',(queue?'Убрать из очереди ':'Включить ')+shortName(s),queue?'close':'play','icon-button play-small',`data-id="${esc(idOf(s))}"`)}</div>`;}
async function catalog(filters={}){const r=await fetch('/api/catalog/search?'+new URLSearchParams({limit:'20',seed:'911',...filters}));if(!r.ok)throw Error('catalog');const data=await r.json();register(data.items);return data;}
function toast(text){const el=document.querySelector('.toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2400);}
function skeleton(){app.className=`variant-${variant}`;app.innerHTML=`<div class="ambient-background"></div><div class="device-top"><span>9:41</span><span class="island"></span><span class="system-icons">▮▮▮ &nbsp; ▰</span></div><div class="telegram-top"><span>‹</span><strong>RadioAtlas</strong><span>•••</span></div><main id="content" tabindex="-1"></main><div id="dock"></div><nav id="navigation" aria-label="Основная навигация" class="glass"></nav><div class="toast glass" role="status" aria-live="polite"></div><dialog id="sheet" aria-label="Подробности"><div id="sheet-inner"></div></dialog><div class="home-indicator"></div>`;main=document.querySelector('#content');modal=document.querySelector('#sheet');modal.addEventListener('close',()=>{state.overlayStack=[];if(focusBefore?.isConnected)focusBefore.focus();});modal.addEventListener('click',e=>{if(e.target===modal)closeSheet();});renderNav();}
function renderNav(){const nav=variant==='a'?[['home','Главная','home'],['search','Поиск','search'],['feed','Лента','feed'],['library','Моё','library']]:[['home','Атлас','globe'],['feed','Лента','feed'],['search','Поиск','search'],['library','Моё','library']];document.querySelector('#navigation').innerHTML=nav.map(([id,label,ic])=>button('nav',label,ic,state.tab===id?'active':'',`data-tab="${id}" ${state.tab===id?'aria-current="page"':''}`)).join('');document.querySelector('#navigation').classList.toggle('feed-nav',state.tab==='feed');}
function pageHeader(title,kicker=''){return `<header class="page-heading"><div>${kicker?`<p class="eyebrow">${kicker}</p>`:''}<h1>${title}</h1></div>${button('theme','Оформление','palette','icon-button glass')}</header>`;}
function liraLine(text){return `<button class="lira-line" data-action="lira">${lira()}<span><strong>Лира</strong><span>${text}</span></span>${icon('spark')}</button>`;}
function storyCard(story,large=false){return `<button class="story-card ${large?'lead-story':''}" data-action="story" data-story="${story.id}">${art(story.art)}<span class="story-caption"><span><small>${story.subtitle}</small><strong>${story.title}</strong></span>${icon('arrow')}</span></button>`;}
function sectionTitle(title,action,label='Все',extra=''){return `<div class="section-heading"><h2>${title}</h2>${action?button(action,label,'arrow','text-button',extra):''}</div>`;}
function homeA(){return `${pageHeader('Открытия','РАДИО МИРА')}<div class="welcome-line">${liraLine('Пойдём за новым звуком?')}${button('firstplay','Включай','play','primary quick-play')}</div>${storyCard(stories[0],true)}<div class="on-cover"><span>Начните с этих эфиров</span>${state.stations.filter(s=>/TSF Jazz|Radio Swiss Jazz/.test(s.name)).map(s=>row(s)).join('')}</div>${sectionTitle('Другое состояние','allstories','Ещё')}<div class="story-rail">${stories.slice(1).map(s=>storyCard(s)).join('')}</div>${sectionTitle('Мир звучит по-разному','worldmap','Карта')}<div class="country-tiles">${countries.slice(0,3).map((c,i)=>`<button data-action="country" data-country="${i}" class="country-tile country-${c[3]}"><span>${c[3]}</span><strong>${c[1]}</strong><small>Открыть эфиры ${icon('arrow')}</small></button>`).join('')}</div>${sectionTitle('Независимый взгляд')}<p class="section-description">Источники со своим характером. Исследуйте, что они выбирают для эфира.</p>${state.stations.filter(s=>/NTS|Worldwide|Meuh/.test(s.name)).map(s=>row(s)).join('')}${sectionTitle('Найти свой звук','genres','Все жанры')}<div class="chips">${['Jazz','Ambient','Funk','Soul','Electronic','Classical'].map(t=>button('tag',t,'','chip',`data-tag="${t.toLowerCase()}"`)).join('')}</div>${personalTeaser()}${community()}`;}
function globe(interactive=false){return `<div class="world-orbit" ${interactive?'aria-label="Направления на карте"':'aria-hidden="true"'}><div class="orbit-line one"></div><div class="orbit-line two"></div><div class="earth-disc"></div><span class="map-dot paris"></span><span class="map-dot tokyo"></span><span class="map-dot rio"></span>${interactive?`<button class="map-label label-paris" data-action="${variant==='a'?'country':'atlas-country'}" data-country="0" aria-label="Исследовать Францию">Париж</button><button class="map-label label-tokyo" data-action="${variant==='a'?'country':'atlas-country'}" data-country="1" aria-label="Исследовать Японию">Токио</button><button class="map-label label-rio" data-action="${variant==='a'?'country':'atlas-country'}" data-country="2" aria-label="Исследовать Бразилию">Рио</button>`:`<span class="map-label label-paris">Париж</span><span class="map-label label-tokyo">Токио</span><span class="map-label label-rio">Рио</span>`}</div>`;}
function homeB(){const c=countries[state.country];return `${pageHeader('На одной волне','ВАШ МУЗЫКАЛЬНЫЙ АТЛАС')}<div class="atlas-intro"><p>У каждого места<br>есть свой звук.</p>${button('firstplay','Включай','play','primary')}</div><div class="atlas-window">${globe(true)}<button class="atlas-lira glass" data-action="lira">${lira()}<span>Куда отправимся?</span>${icon('spark')}</button></div><div class="route-countries" role="group" aria-label="Страна исследования">${countries.map((x,i)=>button('atlas-country',x[1],'',i===state.country?'active':'',`data-country="${i}" aria-pressed="${i===state.country}"`)).join('')}</div><div class="country-heading"><div><span class="eyebrow">ТОЧКА ${String(state.country+1).padStart(2,'0')} / ЭФИРЫ</span><h2>${c[1]}<span>↗</span></h2></div>${button('country','Все эфиры','arrow','round glass',`data-country="${state.country}"`)}</div><div class="route-stations" id="atlas-stations">${state.atlasCache[state.country]?state.atlasCache[state.country].map((s,i)=>row(s,{number:String(i+1).padStart(2,'0')})).join(''):'<p class="loading">Ищем местные эфиры…</p>'}</div>${sectionTitle('Повернуть к другому звуку')}<div class="crossroads">${[['Jazz','jazz','01'],['Электроника','electronic','02'],['Музыка мира','world music','03']].map(([label,tag,n])=>`<button data-action="country-tag" data-tag="${tag}"><span>${n}</span><strong>${label}</strong>${icon('arrow')}</button>`).join('')}</div><div class="route-feature"><span class="eyebrow">МАРШРУТ БЕЗ ГРАНИЦ</span><h2>Ночь движется<br>на запад.</h2><p>Замедляемся вместе с ambient,<br>lounge и downtempo-эфирами.</p>${button('story','По ночным частотам','arrow','glass',`data-story="night"`)}<div class="route-sun" aria-hidden="true"></div></div>${sectionTitle('Следующая остановка','countries','Все страны')}<div class="destination-list">${countries.filter(x=>x!==c).slice(0,3).map(x=>`<button data-action="atlas-country" data-country="${countries.indexOf(x)}"><span>${x[3]}</span><strong>${x[1]}</strong>${icon('arrow')}</button>`).join('')}</div>${personalTeaser()}${community()}`;}
function personalTeaser(){return `<button class="personal-teaser" data-action="nav" data-tab="library">${icon('bookmark')}<span><strong>Ваши маленькие открытия</strong><small>Находки, любимые эфиры и свои подборки</small></span>${icon('arrow')}</button>`;}
function community(){return `<section class="community"><span class="eyebrow">СЛЕДУЮЩАЯ ГЛАВА</span><h3>Радио объединяет вкусы.</h3><p>Здесь будут подборки сообщества.<br>Публичных подборок пока нет.</p>${button('collection','Собрать свою','arrow','text-button')}</section>`;}
async function fillAtlas(){if(state.tab!=='home'||variant!=='b')return;const index=state.country;if(state.atlasCache[index])return;try{const d=await catalog({country:countries[index][0],limit:'4'});state.atlasCache[index]=d.items;if(state.country!==index||state.tab!=='home')return;document.querySelector('#atlas-stations').innerHTML=d.items.map((s,i)=>row(s,{number:String(i+1).padStart(2,'0')})).join('')||'<p>В этой стране пока нет станций.</p>';}catch{const el=document.querySelector('#atlas-stations');if(el)el.innerHTML=button('atlas-retry','Повторить загрузку','arrow','text-button');}}
function renderMain(reset=false){state.generation++;if(state.tab==='home'){main.innerHTML=variant==='a'?homeA():homeB();if(variant==='b'&&state.country!==0)fillAtlas();}else if(state.tab==='feed')main.innerHTML=feed();else if(state.tab==='library')main.innerHTML=library();else main.innerHTML=search();main.className=state.tab==='feed'?'feed-page':'';if(reset)main.scrollTop=0;renderNav();renderDock();}
function nav(tab){if(tab===state.tab){main.scrollTo({top:0,behavior:'auto'});return;}state.scrolls[state.tab]=main.scrollTop;state.tab=tab;renderMain();main.scrollTop=state.scrolls[tab]||0;}
function renderDock(){const el=document.querySelector('#dock');if(state.tab==='feed'||!state.current){el.innerHTML='';return;}const s=state.current;el.innerHTML=`<div class="mini-player glass"><button class="mini-info" data-action="nav" data-tab="feed">${logo(s)}<span><strong>${esc(shortName(s))}</strong><small>${state.playing?'Friday Morning · пример трека':'На паузе · открыть Ленту'}</small></span></button>${state.playing?button('save','Сохранить трек','bookmark','icon-button '+(state.finds.some(x=>x.stationId===idOf(s))?'selected':'')):''}${button('toggle',state.playing?'Пауза':'Включить',state.playing?'pause':'play','icon-button mini-play')}</div>`;}
function play(s){if(!s)return;state.current=s;state.playing=true;renderDock();if(state.tab==='feed'){const pos=main.scrollTop;main.innerHTML=feed();main.scrollTop=pos;}toast('Выбран эфир: '+shortName(s));}
function save(){if(!state.current||!state.playing){toast('Сначала включите эфир');return;}const id=idOf(state.current);if(!state.finds.some(x=>x.stationId===id)){state.finds.unshift({stationId:id,stationName:shortName(state.current),track:'Khruangbin — Friday Morning',time:new Date().toLocaleTimeString('ru',{hour:'2-digit',minute:'2-digit'})});}document.querySelectorAll('[data-action="save"]').forEach(b=>{b.classList.add('selected');b.setAttribute('aria-label','Трек сохранён');});toast('Трек сохранён в «Моё»');}
function feed(){const s=state.current||state.stations[0];if(!s)return '<p>Загружаем эфиры…</p>';return `<div class="feed-header">${button('nav',variant==='a'?'К открытиям':'К Атласу','back','text-button','data-tab="home"')}<span>ЛЕНТА</span>${button('timer',state.timer?`Таймер: ${state.timer} мин`:'Таймер сна','timer','icon-button glass')}</div><div class="feed-card ${variant==='b'?'atlas-feed':''}" tabindex="0" aria-label="Лента эфиров. Стрелки вправо и влево переключают станцию."><div class="feed-card-top"><span class="air-badge">${state.playing?'ЭФИР · МАКЕТ':'НА ПАУЗЕ'}</span><span>${esc(countryName(s.country))}</span></div>${variant==='a'?`<div class="record-stage">${art('feed')}<div class="record-caption">${logo(s)}<span>Прямой эфир<br><b>${esc(shortName(s))}</b></span></div></div>`:`<div class="atlas-feed-scene">${globe()}<span class="frequency-label">${esc(s.countrycode||'FM')}<small>МУЗЫКА МЕСТА</small></span></div>`}<div class="feed-source"><button class="feed-source-name" data-action="source" data-id="${esc(idOf(s))}"><strong>${esc(shortName(s))}</strong><small>Об источнике ${icon('arrow')}</small></button>${button('favorite','Любимая станция','heart','icon-button '+(state.favorites.has(idOf(s))?'selected':''),`data-id="${esc(idOf(s))}" aria-pressed="${state.favorites.has(idOf(s))}"`)}</div><div class="track-block"><span class="eyebrow">ПРИМЕР ТРЕКА</span><div><span><h2>Friday Morning</h2><p>Khruangbin</p></span>${button('save','Сохранить трек','bookmark','round glass '+(state.finds.some(f=>f.stationId===idOf(s))?'selected':''))}</div></div><div class="transport">${button('previous','Предыдущая станция','prev','icon-button')}${button('toggle',state.playing?'Пауза':'Включить',state.playing?'pause':'play','main-play glass')}${button('next','Следующая станция','next','icon-button')}</div><div class="feed-tools">${button('queue','Очередь','queue','text-button')}${button('more','Управление','more','text-button')}</div></div><div class="swipe-hint">← Свайп — другой эфир →</div><div class="feed-context">${liraLine('Исследуем этот источник?')}<p>${esc(s.tags?.split(',').slice(0,4).join(' · ')||'Радио · '+countryName(s.country))}</p>${button('country-by-source','Эфиры: '+countryName(s.country),'arrow','text-button',`data-id="${esc(idOf(s))}"`)}</div>`;}
function library(){return `${pageHeader('Моё','СОБРАНО НА СЛУХ')}<div class="library-tabs"><span>Находки <b>${state.finds.length}</b></span><span>Источники <b>${state.favorites.size}</b></span></div>${sectionTitle('Пойманные треки')}${state.finds.length?state.finds.map(f=>`<button class="find-card" data-action="find" data-id="${esc(f.stationId)}">${icon('bookmark')}<span><strong>${esc(f.track)}</strong><small>${esc(f.stationName)} · ${f.time} · пример</small></span>${icon('arrow')}</button>`).join(''):`<div class="empty-state">${icon('bookmark')}<h3>Услышали своё?</h3><p>Закладка рядом с треком сохранит название и источник. Слушайте дальше.</p>${button('nav','В Ленту','arrow','text-button','data-tab="feed"')}</div>`}${sectionTitle('Любимые источники')}${state.favorites.size?[...state.favorites].map(id=>row(known.get(id))).join(''):'<p class="section-description">Сердце у станции оставляет её здесь — чтобы вернуться в эфир.</p>'}${sectionTitle('Свои подборки','collection','Создать')}<div id="collections">${state.collection?`<button class="find-card" data-action="mycollection"><span class="collection-art">♫</span><span><strong>${esc(state.collection)}</strong><small>${state.collectionIds?.length||0} источников · личная подборка</small></span>${icon('arrow')}</button>`:'<p class="section-description">Соберите любимые источники под свой вечер.</p>'}</div>${button('theme','Оформление и своя тема','palette','settings-row')}${community()}`;}
function search(){return `${pageHeader('Искать','НОВЫЙ ЗВУК РЯДОМ')}<form id="search-form" class="search-form">${icon('search')}<input name="q" aria-label="Станция, страна или жанр" placeholder="Станция, страна, жанр" autocomplete="off"><button aria-label="Найти">${icon('arrow')}</button></form>${sectionTitle('По настроению')}<div class="search-stories">${stories.map(s=>storyCard(s)).join('')}</div>${sectionTitle('По географии','countries','Все страны')}<div class="chips">${countries.map((c,i)=>button('country',c[1],'','chip',`data-country="${i}"`)).join('')}</div>${sectionTitle('По звучанию','genres','Жанры')}<div class="chips">${['Jazz','Funk','Soul','Ambient','Classical','Electronic','Reggae','Rock'].map(t=>button('tag',t,'','chip',`data-tag="${t.toLowerCase()}"`)).join('')}</div>`;}
function openSheet(title,body,{push=false}={}){if(!modal.open){focusBefore=document.activeElement;state.overlayStack=[];}else if(push){state.overlayStack.push({title:document.querySelector('#sheet-title').textContent,html:document.querySelector('#sheet-body').innerHTML,scroll:modal.scrollTop,browse:state.browse});}document.querySelector('#sheet-inner').innerHTML=`<div class="sheet-handle"></div><header class="sheet-header">${state.overlayStack.length?button('sheet-back','Назад','back','icon-button'):''}<h2 id="sheet-title">${esc(title)}</h2>${button('close','Закрыть','close','icon-button glass')}</header><div id="sheet-body">${body}</div>`;if(!modal.open)modal.showModal();modal.scrollTop=0;}
function closeSheet(){modal.close();state.generation++;}
function source(s){openSheet(shortName(s),`<div class="source-profile">${logo(s)}<span class="eyebrow">ИСТОЧНИК · ${esc(countryName(s.country))}</span><h3>${esc(shortName(s))}</h3><p>${esc(s.tags?.split(',').filter(t=>!['aac','mp3'].includes(t)).join(' · ')||'Интернет-радио')}</p></div>${button('play','Включить эфир','play','primary full',`data-id="${esc(idOf(s))}"`)}${button('favorite',state.favorites.has(idOf(s))?'Убрать из любимых':'Любимая станция','heart','settings-row',`data-id="${esc(idOf(s))}"`)}${button('enqueue','Добавить в очередь','queue','settings-row',`data-id="${esc(idOf(s))}"`)}${s.homepage&&/^https?:/.test(s.homepage)?`<a class="settings-row" href="${esc(s.homepage)}" target="_blank" rel="noopener noreferrer">${icon('link')}<span>Сайт станции</span>${icon('arrow')}</a>`:''}<p class="footnote">Название, страна и теги — из каталога. Теги описывают станцию, а не текущий трек.</p>`,{push:modal.open});}
async function browse(title,filters={},desc='',artKind=''){const picks=artKind?state.stations.filter(s=>({jazz:/TSF Jazz|Swiss Jazz|FIP Jazz/,night:/Groove Salad|Drone Zone|Deep Space/,groove:/Meuh|FIP Groove/,world:/Worldwide/})[artKind]?.test(s.name)):[];openSheet(title,`${artKind?art(artKind):''}${desc?`<p class="browse-description">${esc(desc)}</p>`:''}${picks.length?`<div class="curated-intro"><span class="eyebrow">НАЧНИТЕ ЗДЕСЬ</span>${picks.map(s=>row(s)).join('')}</div><h3 class="catalog-heading">Продолжить исследование</h3>`:''}<div class="catalog-meta"></div><div id="catalog-results"><p class="loading">Открываем эфиры…</p></div><div id="catalog-more"></div>`,{push:modal.open});const token=++state.generation;state.browse={title,filters,token,cursor:null};await loadPage(false);}
async function loadPage(more){const b=state.browse;if(!b)return;const token=b.token;const target=document.querySelector('#catalog-more');if(target)target.innerHTML='<p class="loading">Загружаем…</p>';try{const data=await catalog({...b.filters,...(more&&b.cursor?{cursor:b.cursor}:{})});if(state.browse!==b||state.generation!==token||!modal.open)return;const results=document.querySelector('#catalog-results');if(!results)return;const html=data.items.map(s=>row(s)).join('');if(more)results.insertAdjacentHTML('beforeend',html);else results.innerHTML=html||'<p class="empty-state">Эфиры не найдены. Попробуйте другое направление.</p>';document.querySelector('.catalog-meta').textContent=`${data.total.toLocaleString('ru')} станций · полный каталог`;b.cursor=data.nextCursor;document.querySelector('#catalog-more').innerHTML=data.nextCursor?button('loadmore','Ещё станции','down','load-more glass'):'';}catch{if(state.browse!==b||!modal.open)return;document.querySelector('#catalog-more').innerHTML=`<p class="footnote">Каталог не ответил. Уже открытые эфиры сохранены.</p>${button(more?'loadmore':'retrycatalog','Повторить','arrow','load-more glass')}`;if(!more)document.querySelector('#catalog-results').innerHTML='';}}
function showCountries(){openSheet('Куда отправимся?',`<label class="country-search">${icon('search')}<input id="country-filter" placeholder="Найти страну" aria-label="Найти страну"></label><div id="all-countries">${countries.map((c,i)=>button('country',c[1],'arrow','settings-row',`data-country="${i}"`)).join('')}</div>`,{push:modal.open});catalog({limit:'1'}).then(d=>{const el=document.querySelector('#all-countries');if(!el)return;state.allCountries=d.facets.countries;el.innerHTML=state.allCountries.map(c=>button('catalog-country',countryName(c),'arrow','settings-row',`data-value="${esc(c)}"`)).join('');}).catch(()=>toast('Показаны основные направления'));}
function showGenres(){openSheet('В каком ритме?',`<div class="genre-grid">${['Jazz','Ambient','Funk','Soul','Electronic','Classical','Reggae','Rock','Disco','House','Blues','World music','Downtempo','Hip hop','Piano','Experimental'].map(t=>button('tag',t,'arrow','genre-card',`data-tag="${t.toLowerCase()}"`)).join('')}</div>`,{push:modal.open});}
function showTimer(){openSheet('Таймер сна',`<div class="timer-art">${icon('timer')}<h3>${state.timer?state.timer+' минут':'Можно засыпать.'}</h3><p>Радио остановится в выбранное время.</p></div><div class="timer-options">${[15,30,45,60,90].map(n=>button('settimer',n+' мин',state.timer===n?'check':'','chip',`data-minutes="${n}"`)).join('')}</div><label class="custom-minutes">Своё время, минут<input id="minutes" type="number" value="20" min="1" max="240"></label>${button('customtimer','Установить','timer','primary full')}${button('settimer','Выключить таймер','','settings-row','data-minutes="0"')}`,{push:modal.open});}
function setTimer(n){state.timer=n;clearTimeout(timerHandle);if(n)timerHandle=setTimeout(()=>{state.playing=false;state.timer=0;renderDock();if(state.tab==='feed')renderMain();toast('Таймер сна остановил эфир');},n*60000);closeSheet();if(state.tab==='feed'){const y=main.scrollTop;main.innerHTML=feed();main.scrollTop=y;}toast(n?'Таймер установлен: '+n+' мин':'Таймер выключен');}
function theme(){openSheet('Ваш RadioAtlas',`<p class="browse-description">Музыка меняет настроение.<br>Пространство может меняться вместе с ней.</p><div class="theme-grid">${[['light','Свет'],['dark','Ночь'],['rose','Розовый кварц'],['ocean','Лагуна']].map(([id,n])=>`<button class="theme-choice ${id} ${state.theme===id?'chosen':''}" data-action="settheme" data-theme="${id}"><i></i><span>${n}</span>${state.theme===id?icon('check'):''}</button>`).join('')}</div><h3>Своя палитра</h3><div class="color-inputs"><label>Первый цвет<input type="color" id="color1" value="${state.color1||'#efb798'}"></label><label>Второй цвет<input type="color" id="color2" value="${state.color2||'#b7c9d1'}"></label></div>${button('gradient','Применить градиент','palette','settings-row')}<label class="upload-label">${icon('palette')}<span>Своя картинка<input id="background-file" type="file" accept="image/*"></span></label><label class="settings-row toggle-row"><span>Уменьшить прозрачность</span><input id="opaque" type="checkbox" ${state.opaque?'checked':''}></label><p class="footnote">Картинка остаётся в браузере. Оформление применяется только к этому варианту.</p>`);}
function applyTheme(name){state.theme=name;app.dataset.theme=name;}
function showMore(){openSheet('Управление эфиром',`<label class="volume-label">${icon('volume')}<span>Громкость <output id="volume-value">${state.volume}%</output></span><input id="volume" type="range" min="0" max="100" value="${state.volume}"></label>${button('timer',state.timer?'Таймер: '+state.timer+' мин':'Таймер сна','timer','settings-row')}${button('queue','Очередь эфиров','queue','settings-row')}${state.current?button('source','Об источнике','globe','settings-row',`data-id="${esc(idOf(state.current))}"`):''}${button('theme','Оформление','palette','settings-row')}<p class="footnote">В макете проверяется расположение и поведение управления. Аудиопоток не подключён.</p>`);}
function showQueue(){openSheet('Дальше в эфире',`${state.queue.length?state.queue.map(id=>row(known.get(id),{queue:true})).join(''):'<div class="empty-state">'+icon('queue')+'<h3>Ваша очередь</h3><p>Добавляйте станции из карточки источника. Исследование продолжится, эфир останется прежним.</p></div>'}`,{push:modal.open});}
function nextStation(delta){const list=state.queue.length?state.queue.map(id=>known.get(id)):state.stations;const index=list.findIndex(s=>idOf(s)===idOf(state.current||state.stations[0]));play(list[(Math.max(0,index)+delta+list.length)%list.length]);}
function liraSheet(){openSheet('Лира · ваш проводник',`<div class="lira-profile">${lira()}<h3>А если послушать<br>что-то незнакомое?</h3><p>Начнём с одного из направлений.</p></div>${stories.map(s=>`<button class="lira-suggestion" data-action="story" data-story="${s.id}"><span><strong>${s.title}</strong><small>${s.subtitle}</small></span>${icon('arrow')}</button>`).join('')}<p class="footnote">В этом макете — готовые направления. Живой диалог с Лирой подключается после выбора дизайна.</p>`,{push:modal.open});}
app.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,s=known.get(b.dataset.id);switch(action){
case 'nav': if(modal.open)closeSheet();nav(b.dataset.tab);break;
case 'firstplay':play(state.stations[0]);break;
case 'play':play(s);break;
case 'toggle':if(!state.current)state.current=state.stations[0];state.playing=!state.playing;renderDock();if(state.tab==='feed'){const y=main.scrollTop;main.innerHTML=feed();main.scrollTop=y;}break;
case 'save':save();break;
case 'source':source(s);break;
case 'favorite':{if(state.favorites.has(idOf(s)))state.favorites.delete(idOf(s));else state.favorites.add(idOf(s));b.classList.toggle('selected',state.favorites.has(idOf(s)));b.setAttribute('aria-pressed',state.favorites.has(idOf(s)));toast(state.favorites.has(idOf(s))?'Станция в любимых':'Станция убрана из любимых');break;}
case 'story':{const story=stories.find(s=>s.id===b.dataset.story);browse(story.title,story.tag?{tag:story.tag}:{mood:story.mood},story.desc,story.art);break;}
case 'allstories':openSheet('Музыкальные истории',`<div class="search-stories">${stories.map(s=>storyCard(s)).join('')}</div>`);break;
case 'country':{const c=countries[Number(b.dataset.country)];browse(c[1],{country:c[0]},'Слушайте местные источники и находите свой звук.');break;}
case 'catalog-country':browse(countryName(b.dataset.value),{country:b.dataset.value});break;
case 'country-by-source':browse(countryName(s.country),{country:s.country});break;
case 'atlas-country':state.country=Number(b.dataset.country);if(modal.open)closeSheet();if(state.tab!=='home')nav('home');else {main.innerHTML=homeB();main.scrollTop=0;}fillAtlas();break;
case 'atlas-retry':fillAtlas();break;
case 'worldmap':openSheet('Мир на слух',`<div class="atlas-window">${globe(true)}</div><p class="browse-description">Выберите направление на карте или откройте полный список стран.</p>${button('countries','Все страны','globe','settings-row')}${countries.map((c,i)=>button('country',c[1],'arrow','settings-row',`data-country="${i}"`)).join('')}`);break;
case 'countries':showCountries();break;
case 'genres':showGenres();break;
case 'tag':browse(b.textContent.trim(),{tag:b.dataset.tag});break;
case 'country-tag':browse(b.textContent.trim().slice(2).trim()+' · '+countries[state.country][1],{tag:b.dataset.tag,country:countries[state.country][0]});break;
case 'loadmore':loadPage(true);break;
case 'retrycatalog':loadPage(false);break;
case 'close':closeSheet();break;
case 'sheet-back':{const prev=state.overlayStack.pop();if(prev){state.browse=prev.browse;if(state.browse)state.generation=state.browse.token;openSheet(prev.title,prev.html);modal.scrollTop=prev.scroll;}break;}
case 'timer':showTimer();break;
case 'settimer':setTimer(Number(b.dataset.minutes));break;
case 'customtimer':{const n=Number(document.querySelector('#minutes').value);if(n>=1&&n<=240)setTimer(n);else toast('От 1 до 240 минут');break;}
case 'theme':theme();break;
case 'settheme':app.style.removeProperty('--custom-bg');applyTheme(b.dataset.theme);theme();break;
case 'gradient':state.color1=document.querySelector('#color1').value;state.color2=document.querySelector('#color2').value;app.style.setProperty('--custom-bg',`linear-gradient(145deg,${state.color1},${state.color2})`);applyTheme('custom');toast('Ваш градиент применён');break;
case 'more':showMore();break;
case 'queue':showQueue();break;
case 'enqueue':if(!state.queue.includes(idOf(s)))state.queue.push(idOf(s));toast('Станция добавлена в очередь');break;
case 'removequeue':state.queue=state.queue.filter(id=>id!==idOf(s));showQueue();break;
case 'next':nextStation(1);break;
case 'previous':nextStation(-1);break;
case 'lira':liraSheet();break;
case 'collection':openSheet('Своя подборка',`<p class="browse-description">Соберём в неё любимые источники этого просмотра.</p><form id="collection-form"><label class="field-label">Название<input name="title" required maxlength="60" placeholder="Например, медленное утро" value="${esc(state.collection||'')}"></label><button class="primary full">Создать подборку</button></form>`,{push:modal.open});break;
case 'mycollection':openSheet(state.collection,state.collectionIds?.length?state.collectionIds.map(id=>row(known.get(id))).join(''):'<p class="browse-description">При создании этой подборки не было выбранных источников.</p>');break;
case 'find':{const f=state.finds.find(f=>f.stationId===b.dataset.id);openSheet('Ваша находка',`<div class="find-detail">${icon('bookmark')}<h3>${esc(f.track)}</h3><p>${esc(f.stationName)} · ${f.time}<br>Пример трека для макета</p></div><a class="settings-row" target="_blank" rel="noopener noreferrer" href="https://music.yandex.ru/search?text=${encodeURIComponent(f.track)}">Яндекс Музыка ${icon('arrow')}</a><a class="settings-row" target="_blank" rel="noopener noreferrer" href="https://open.spotify.com/search/${encodeURIComponent(f.track)}">Spotify ${icon('arrow')}</a>${button('copyfind','Скопировать название','link','settings-row',`data-track="${esc(f.track)}"`)}${button('source','Вернуться к источнику','globe','settings-row',`data-id="${esc(f.stationId)}"`)}`);break;}
case 'copyfind':try{await navigator.clipboard.writeText(b.dataset.track);toast('Название скопировано');}catch{toast('Буфер недоступен. Трек остаётся в находках.');}break;
}});
app.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='search-form'){const q=new FormData(e.target).get('q').trim();if(q)browse(q,{q});}if(e.target.id==='collection-form'){state.collection=new FormData(e.target).get('title').trim();state.collectionIds=[...state.favorites];closeSheet();if(state.tab==='library')renderMain();toast('Личная подборка создана');}});
app.addEventListener('input',e=>{if(e.target.id==='country-filter'){const q=e.target.value.toLocaleLowerCase();document.querySelectorAll('#all-countries button').forEach(b=>b.hidden=!b.textContent.toLocaleLowerCase().includes(q));}if(e.target.id==='volume'){state.volume=Number(e.target.value);document.querySelector('#volume-value').textContent=state.volume+'%';}});
app.addEventListener('change',e=>{if(e.target.id==='opaque'){state.opaque=e.target.checked;app.classList.toggle('opaque',state.opaque);}if(e.target.id==='background-file'){const file=e.target.files[0];if(!file)return;if(!file.type.startsWith('image/')||file.size>12*1024*1024){toast('Выберите картинку до 12 МБ');return;}if(state.imageUrl)URL.revokeObjectURL(state.imageUrl);state.imageUrl=URL.createObjectURL(file);app.style.setProperty('--custom-bg',`url("${state.imageUrl}")`);applyTheme('custom');toast('Ваш фон применён');}});
app.addEventListener('pointerdown',e=>{if(e.target.closest('.feed-card')&&!e.target.closest('button,input'))feedStart={x:e.clientX,y:e.clientY};else feedStart=null;});
app.addEventListener('pointerup',e=>{if(!feedStart)return;const dx=e.clientX-feedStart.x,dy=e.clientY-feedStart.y;feedStart=null;if(Math.abs(dx)>65&&Math.abs(dx)>Math.abs(dy)*1.5)nextStation(dx<0?1:-1);});
app.addEventListener('keydown',e=>{if(e.target.classList.contains('feed-card')&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();nextStation(e.key==='ArrowRight'?1:-1);}});
async function init(){skeleton();main.innerHTML='<p class="loading">Настраиваемся на мир…</p>';try{const r=await fetch('stations.json');state.stations=await r.json();register(state.stations);state.current=state.stations[0];state.atlasCache[0]=state.stations.filter(s=>s.country==='France').slice(0,3);renderMain(true);}catch{main.innerHTML='<p class="empty-state">Не удалось открыть данные макета. Перезагрузите страницу.</p>';}}
init();

window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==window.parent)return;const view=e.data?.radioatlasView;if(!['home','feed','timer','theme'].includes(view))return;if(modal.open)closeSheet();if(view==='timer'){nav('feed');showTimer();}else if(view==='theme'){theme();}else{nav(view);main.scrollTop=0;}});
